	sections = {
		{
			title = "Summary",
			text = [=[The Qiraji are an ancient, thinking insect people of the southern desert. They built the fortress of Ahn'Qiraj in {link:silithus}Silithus{/link}, and from it they command the silithid, the swarming insects that fill the hives of the land. The silithid are countless, and more hatch every hour. The Qiraji are their masters: not beasts but schemers, with generals and kings of their own.]=],
		},
		{
			title = "Origins",
			text = [=[The oldest histories of {link:kalimdor}Kalimdor{/link} tell of the aqir, an insect empire that warred with the ancient trolls. When the aqir were driven back, part of their kind withdrew to the south, to the land that would become {link:silithus}Silithus{/link}, and there became the Qiraji. The night elves' book of the war says that the Qiraji once vied for mastery over much of Kalimdor.]=],
