Add({
	kind = "topic",
	id = "war-of-the-shifting-sands",
	title = "War of the Shifting Sands",
	category = "event",
	region = "silithus",
	unlock = {
		{ type = "read" },
		{ type = "book", name = "The War of the Shifting Sands" },
		{ type = "quest", id = 8519 },
	},
	sections = {
		{
			title = "Summary",
			text = [=[The War of the Shifting Sands was fought nearly a thousand years ago between the {link:night-elves}night elves{/link} and the {link:qiraji}Qiraji{/link} of Ahn'Qiraj. It ended not in victory but in a prison.]=],
		},
		{
			title = "The Invasion",
			text = [=[From Ahn'Qiraj, the {link:qiraji}Qiraji{/link} marched out under General Rajaxx, with endless swarms of silithid behind them. {link:fandral-staghelm}Fandral Staghelm{/link} gathered the armies of the night elves against them, and his son {link:valstann-staghelm}Valstann{/link} fought at his side. The night elves' book of the war says that Fandral ordered Valstann to hold {link:southwind-village}Southwind Village{/link}. A journal found in its ruins tells more: the Twin Emperors of Ahn'Qiraj laid a trap there, Valstann was taken, and Rajaxx put him to death before his father's army. The war went on for months. At last all {link:silithus}Silithus{/link} was lost, and the broken {link:night-elves}night elf{/link} army was driven back through {link:un-goro-crater}Un'Goro{/link} to {link:tanaris}Tanaris{/link}.]=],
		},
		{
			title = "The Dragons",
			text = [=[There, humbled, {link:fandral-staghelm}Fandral{/link} went to Anachronos, son of {red:nozdormu}Nozdormu{/red}, and begged for the aid of the bronze dragons. Anachronos refused, until the {link:qiraji}Qiraji{/link} dared to attack the {link:caverns-of-time}Caverns of Time{/link}. Even the bronze flight could not hold back the swarm, so Anachronos called on the children of the other Aspects. Merithra came for {red:ysera}Ysera{/red}'s flight, Caelestrasz for {link:alexstrasza}Alexstrasza{/link}'s and Arygos for {red:malygos}Malygos{/red}'s. High above Ahn'Qiraj, they saw that no amount of force could end the war. They resolved to seal the enemy in its own city.]=],
		},
		{
			title = "The Wall and the Scepter",
			text = [=[Drawing on the power of both the night elves and the dragons, they raised a great barrier around Ahn'Qiraj. Merithra, Caelestrasz and Arygos threw themselves against the {link:qiraji}Qiraji{/link} to buy time, while Anachronos and {link:fandral-staghelm}Fandral{/link} sealed the gate. When it was done, Anachronos gave Fandral a scepter that could open the barrier again. The Arch Druid, grieving for his son, hurled it against the barrier and shattered it. Anachronos gathered the pieces and gave them into the keeping of the four great dragonflights, so that no one could easily make it whole.]=],
		},
	},
})

