			hint = [=[Seek the resting place of the bronze dragons for the watcher.]=],
			unlock = {
				{ type = "quest", id = 8286 },
			},
			text = [=[Baristolth could not act until he knew one thing: whether the master who saved him had returned to the world. He sent a messenger to the {link:caverns-of-time}Caverns of Time{/link} in {link:tanaris}Tanaris{/link}, to find Anachronos of the brood of {red:nozdormu}Nozdormu{/red}. When the answer came, he said that all was as it should be. The great one had risen, and his long watch was coming to an end. A second war was coming to the desert.]=],
